function introCard() {
  return el("div", { class: "card" },
    el("p", { class: "card-title" }, "Your app, explained"),
    el("p", { class: "card-sub" },
      "Your bakery app and this app are twins under the hood — they share the same engine, one improvement at a time. This guide explains the engine in everyday words, so the two never feel confusing."),
    el("p", { class: "card-sub" },
      "The twins came back together on 28 September 2026. Between 20 and 28 September they were briefly different: your bakery app gained a bread-only tool for planning bake days, and this app left it out, because posting pouches of jerky has no bake day in it. You then asked for it to be copied over exactly as it is, so it now runs here too — carrying the bakery's own words (ovens, pans, dough, mixers, bake day). That is on purpose, not an oversight. The arithmetic underneath is about people, machines and hours, and that part is not about bread at all."),
    el("p", { class: "card-sub" },
      "Everything else about the two apps is still the same code, and future improvements still arrive here the same way."),
    el("p", { class: "card-sub" },
      "It lives only here in Munchies Furkidz — your bakery app doesn't need it."));
}

function analogyRows(rows) {
  return rows.map(([term, meaning, analogy]) =>
    el("div", { class: "card" },
      el("p", { class: "card-title" }, term),
      el("p", { class: "card-sub" }, meaning),
      el("p", { class: "hint" }, "Analogy: " + analogy)));
}
